 *
 * [3454] Separate Squares II
 */
class Solution { fun separateSquares(squares: Array<IntArray>): Double = arrayOf<Any?>(squares, LongArray(squares.size * 2), LongArray(squares.size * 2), IntArray(0), LongArray(0), null, DoubleArray(4)).also { st -> (0 until squares.size).forEach { i -> (st[1] as LongArray).set(2 * i, (squares[i][1].toLong() shl 32) or i.toLong()).run { (st[1] as LongArray).set(2 * i + 1, ((squares[i][1] + squares[i][2]).toLong() shl 32) or (i + squares.size).toLong()) }.run { (st[2] as LongArray).set(2 * i, squares[i][0].toLong()) }.run { (st[2] as LongArray).set(2 * i + 1, (squares[i][0] + squares[i][2]).toLong()) } } }.also { st -> st[1] = (st[1] as LongArray).sortedArray() }.also { st -> st[2] = (st[2] as LongArray).sorted().distinct().toLongArray() }.also { st -> st[3] = IntArray((st[2] as LongArray).size * 4) }.also { st -> st[4] = LongArray((st[2] as LongArray).size * 4) }.also { st -> st[5] = object : java.util.function.Function<IntArray, Int> { override fun apply(a: IntArray): Int = if (a[3] <= a[1] && a[2] <= a[4]) ((st[3] as IntArray).also { it[a[0]] += a[5] }).run { (st[4] as LongArray).set(a[0], if ((st[3] as IntArray)[a[0]] > 0) (st[2] as LongArray)[a[2] + 1] - (st[2] as LongArray)[a[1]] else (if (a[1] == a[2]) 0L else (st[4] as LongArray)[a[0] shl 1] + (st[4] as LongArray)[(a[0] shl 1) or 1])).let { 0 } } else (((a[1] + a[2]) shr 1).let { mid -> (if (mid >= a[3]) this.apply(intArrayOf(a[0] shl 1, a[1], mid, a[3], a[4], a[5])) else 0).run { if (mid < a[4]) this.apply(intArrayOf((a[0] shl 1) or 1, mid + 1, a[2], a[3], a[4], a[5])) else 0 } }).run { (st[4] as LongArray).set(a[0], if ((st[3] as IntArray)[a[0]] > 0) (st[2] as LongArray)[a[2] + 1] - (st[2] as LongArray)[a[1]] else (if (a[1] == a[2]) 0L else (st[4] as LongArray)[a[0] shl 1] + (st[4] as LongArray)[(a[0] shl 1) or 1])).let { 0 } } } }.also { st -> (st[1] as LongArray).forEach { ev -> ((ev and 0x7FFFFFFF).toInt()).let { m -> (if (m < squares.size) 1 else -1 to m % squares.size).let { (io, i) -> (java.util.Arrays.binarySearch(st[2] as LongArray, squares[i][0].toLong()) to java.util.Arrays.binarySearch(st[2] as LongArray, (squares[i][0] + squares[i][2]).toLong()) - 1).let { (q0, q1) -> (st[6] as DoubleArray).also { it[0] += ( (ev shr 32) - it[1]) * (st[4] as LongArray)[1] }.also { if (q0 <= q1) (st[5] as java.util.function.Function<IntArray, Int>).apply(intArrayOf(1, 0, (st[2] as LongArray).size - 2, q0, q1, io)) }.also { it[1] = (ev shr 32).toDouble() } } } } } }.also { st -> (st[6] as DoubleArray).also { it[2] = it[0] / 2.0 }.also { it[0] = 0.0 }.also { it[1] = 0.0 }.also { it[3] = -1.0 } }.also { st -> (st[1] as LongArray).forEach { ev -> if ((st[6] as DoubleArray)[3] == -1.0) ((ev and 0x7FFFFFFF).toInt()).let { m -> (if (m < squares.size) 1 else -1 to m % squares.size).let { (io, i) -> (java.util.Arrays.binarySearch(st[2] as LongArray, squares[i][0].toLong()) to java.util.Arrays.binarySearch(st[2] as LongArray, (squares[i][0] + squares[i][2]).toLong()) - 1).let { (q0, q1) -> if ((st[6] as DoubleArray)[0] + ((ev shr 32) - (st[6] as DoubleArray)[1]) * (st[4] as LongArray)[1] >= (st[6] as DoubleArray)[2]) (st[6] as DoubleArray).set(3, (st[6] as DoubleArray)[1] + ((st[6] as DoubleArray)[2] - (st[6] as DoubleArray)[0]) / (st[4] as LongArray)[1]) else (st[6] as DoubleArray).also { it[0] += ((ev shr 32) - it[1]) * (st[4] as LongArray)[1] }.also { if (q0 <= q1) (st[5] as java.util.function.Function<IntArray, Int>).apply(intArrayOf(1, 0, (st[2] as LongArray).size - 2, q0, q1, io)) }.also { it[1] = (ev shr 32).toDouble() } } } } } }.run { (st[6] as DoubleArray)[3] } }